static account_template_t *account_template_create_internal(
    char *ad_account_id,
    list_t *ad_account_ids,
    list_t *ade_columns,
    any_type_t *attribution_type,
    double *click_window_days,
    list_t *columns,
    conversion_report_time_type_t *conversion_report_time_type,
    creation_source_t *creation_source,
    list_t *custom_column_ids,
    char *display_metadata,
    double *engagement_window_days,
    char *filters_json,
    pinterest_rest_api_granularity__e granularity,
    char *id,
    list_t *ingestion_sources,
    int *is_default,
    int *is_deleted,
    int *is_owned_by_user,
    int *is_scheduled,
    char *name,
    double *report_end_relative_days_in_past,
    pinterest_rest_api_data_output_format__e report_format,
    pinterest_rest_api_metrics_reporting_level__e report_level,
    double *report_start_relative_days_in_past,
    reporting_time_zone_t *reporting_time_zone,
    any_type_t *sort_by,
    char *type,
    double *updated_time,
    char *user_id,
    double *view_window_days
    ) {
    account_template_t *account_template_local_var = malloc(sizeof(account_template_t));
    if (!account_template_local_var) {
        return NULL;
    }
    memset(account_template_local_var, 0, sizeof(account_template_t));
    account_template_local_var->_library_owned = 1;
    account_template_local_var->ad_account_id = ad_account_id;
    account_template_local_var->ad_account_ids = ad_account_ids;
    account_template_local_var->ade_columns = ade_columns;
    account_template_local_var->attribution_type = attribution_type;
    account_template_local_var->click_window_days = click_window_days;
    account_template_local_var->columns = columns;
    account_template_local_var->conversion_report_time_type = conversion_report_time_type;
    account_template_local_var->creation_source = creation_source;
    account_template_local_var->custom_column_ids = custom_column_ids;
    account_template_local_var->display_metadata = display_metadata;
    account_template_local_var->engagement_window_days = engagement_window_days;
    account_template_local_var->filters_json = filters_json;
    account_template_local_var->granularity = granularity;
    account_template_local_var->id = id;
    account_template_local_var->ingestion_sources = ingestion_sources;
    account_template_local_var->is_default = is_default;
    account_template_local_var->is_deleted = is_deleted;
    account_template_local_var->is_owned_by_user = is_owned_by_user;
    account_template_local_var->is_scheduled = is_scheduled;
    account_template_local_var->name = name;
    account_template_local_var->report_end_relative_days_in_past = report_end_relative_days_in_past;
    account_template_local_var->report_format = report_format;
    account_template_local_var->report_level = report_level;
    account_template_local_var->report_start_relative_days_in_past = report_start_relative_days_in_past;
    account_template_local_var->reporting_time_zone = reporting_time_zone;
    account_template_local_var->sort_by = sort_by;
    account_template_local_var->type = type;
    account_template_local_var->updated_time = updated_time;
    account_template_local_var->user_id = user_id;
    account_template_local_var->view_window_days = view_window_days;
    return account_template_local_var;
}

