    // define the local variable for account_template->engagement_window_days
    double *engagement_window_days_local_var = NULL;

    char *filters_json_local_str = NULL;

    // define the local variable for account_template->granularity
    pinterest_rest_api_granularity__e granularity_local_nonprim = 0;

    char *id_local_str = NULL;

    // define the local list for account_template->ingestion_sources
    list_t *ingestion_sourcesList = NULL;

