    int *is_default_local_var = NULL;

    // define the local variable for account_template->is_deleted
    int *is_deleted_local_var = NULL;

    // define the local variable for account_template->is_owned_by_user
    int *is_owned_by_user_local_var = NULL;

    // define the local variable for account_template->is_scheduled
    int *is_scheduled_local_var = NULL;

    char *name_local_str = NULL;

    // define the local variable for account_template->report_end_relative_days_in_past
    double *report_end_relative_days_in_past_local_var = NULL;

    // define the local variable for account_template->report_format
    pinterest_rest_api_data_output_format__e report_format_local_nonprim = 0;

    // define the local variable for account_template->report_level
    pinterest_rest_api_metrics_reporting_level__e report_level_local_nonprim = 0;

    // define the local variable for account_template->report_start_relative_days_in_past
    double *report_start_relative_days_in_past_local_var = NULL;

